def main():
    plan=json.loads((OUT/'attempt-02/plan.json').read_text());c=load(OUT/'attempt-02/catalog.json.gz');admission=load(OUT/'attempt-02/admission.json.gz');raw=load(OUT/'recovered-left-zero-seven.json.gz');recovery=json.loads((OUT/'recovery-summary.json').read_text());audit=json.loads((OUT/'recovery-audit.json').read_text());compact=json.loads((OUT/'compaction-summary.json').read_text());caudit=json.loads((OUT/'compaction-audit.json').read_text());prior=json.loads((OUT/'attempt-01/cost-summary.json').read_text());paudit=json.loads((OUT/'attempt-01/audit.json').read_text());cost=json.loads((OUT/'attempt-02/cost-summary.json').read_text());native=load(OUT/'compaction-native.json.gz')
    if any(v['status']!='passed' for v in (audit,caudit,paudit)):raise ValueError('all complete independent audit gates are required')
